// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testFuzz_property(address nonOwner, bytes calldata data) public {
        vm.assume(nonOwner != c.Owner());
        vm.deal(nonOwner, 0);
        vm.prank(nonOwner);
        bool ok;
        try c.Command(nonOwner, data) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
